cd D:/Repos/angular-jig/src/app && mk() { # name Class Title Note
  local name=$1 cls=$2 title=$3 note=$4
  mkdir -p "$name"
  cat > "$name/$name.ts" <<EOF
import { Component } from '@angular/core';
import { HlmTypographyImports } from '@spartan-ng/helm/typography';

// Placeholder. The $title screen is built in a later stage.
@Component({
  selector: 'app-$name',
  imports: [HlmTypographyImports],
  templateUrl: './$name.html',
  styleUrl: './$name.css',
})
export class $cls {}
EOF
  cat > "$name/$name.html" <<EOF
<section class="$name">
  <h1 hlmH1>$title</h1>
  <p hlmMuted>$note</p>
</section>
EOF
  cat > "$name/$name.css" <<EOF
@reference "../../styles.css";

.$name { @apply grid content-start gap-2 p-6; }
EOF
}
mk dashboard Dashboard "Operations Dashboard" "Stat tiles and top heroes arrive in a later stage."
mk heroes Heroes "Roster" "The hero table arrives in a later stage."
mk hero-detail HeroDetail "Hero Detail" "The hero detail screen arrives in a later stage."
