mk threats Threats "Threats" "The threat register arrives in a later stage."
mk recruit Recruit "Recruit" "The recruiting form arrives in a later stage."
mk settings Settings "Settings" "Console preferences arrive in a later stage."
sed -i 's/^\(\s*\)<\/section>/\1<\/section>/' dashboard/dashboard.html; cat hero-detail/hero-detail.ts hero-detail/hero-detail.html heroes/heroes.css

